CREATE TABLE calendar_preferences(household_id TEXT NOT NULL, member_id TEXT NOT NULL, week_start TEXT NOT NULL DEFAULT 'monday' CHECK(week_start IN ('monday','sunday')), revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>=1), PRIMARY KEY(household_id,member_id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,member_id));
